CREATE TABLE product_attr (
  product_id integer,
  attr_name text,
  attr_value text
);
-- e.g. (10,'price','19.99'), (10,'weight_kg','0.5'), (10,'color','red')
-- query: total price of products in a cart
SELECT sum(attr_value::numeric)
FROM product_attr
WHERE attr_name = 'price' AND product_id IN (10, 11, 12);
